// Flag open requests that are overdue or due within WARN_DAYS.
const WARN_DAYS = 7;
const CLOSED = ['Completed - access fulfilled', 'Completed - erased', 'Completed - refused', 'Closed - not verified'];
const today = new Date(new Date().toISOString().slice(0, 10));

const atRisk = $input.all()
  .map((i) => i.json)
  .filter((r) => r.RequestId && !CLOSED.includes(r.Status))
  .map((r) => {
    const daysLeft = Math.round((new Date(r.Deadline) - today) / 86400000);
    return { ...r, daysLeft };
  })
  .filter((r) => r.daysLeft <= WARN_DAYS)
  .sort((a, b) => a.daysLeft - b.daysLeft);

if (atRisk.length === 0) return [];

const lines = atRisk.map((r) => {
  const when = r.daysLeft < 0 ? `*OVERDUE by ${-r.daysLeft}d*` : `due in ${r.daysLeft}d`;
  return `• ${r.RequestId} (${r.RequestType}) ${when}, deadline ${r.Deadline}, status: ${r.Status}`;
});

return [{ json: { count: atRisk.length, summary: lines.join('\n') } }];

